#nullable enable // autogenerated

using MVZ2.Managers;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Localization
{
    [RequireComponent(typeof(SpriteRenderer))]
    public class SpriteRendererTranslator : TranslateComponentSprite<SpriteRenderer>
    {
        protected override Sprite? GetKeyInner()
        {
            return Component?.sprite;
        }
        protected override void Translate(string language)
        {
            base.Translate(language);
            if (Component.Exists() && Key.Exists())
            {
                var main = MainManager.Instance;
                var context = main.GetSpriteVariantContenxt();
                context.languageCode = language;
                Component.sprite = MainManager.Instance.GetFinalSprite(Key, context);
            }
        }
    }
}
